// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 payoffType, uint8 payoffDirection, bytes30 data) public {
        // Bound enum-like values to valid ranges
        vm.assume(payoffType <= 2);
        vm.assume(payoffDirection <= 1);

        // Create a PayoffDefinition struct
        PayoffDefinitionLib.PayoffType pType = PayoffDefinitionLib.PayoffType(payoffType);
        PayoffDefinitionLib.PayoffDirection pDir = PayoffDefinitionLib.PayoffDirection(payoffDirection);
        PayoffDefinition memory def = PayoffDefinition({
            payoffType: pType,
            payoffDirection: pDir,
            data: data
        });

        // Initialize C with this definition (we need a mock productInfo)
        // But first we need to handle the oracle requirement - use a mock oracle
        MockOracle oracle = new MockOracle();

        // We need to call initialize - but it requires msg.sender to be a controller
        // Use a mock controller that isContract returns true and allows initialization
        MockController mcontroller = new MockController();

        vm.startPrank(address(mcontroller));
        c.initialize(IProduct.ProductInfo({
            name: "",
            symbol: "",
            payoffDefinition: def,
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18.wrap(1e18),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(0),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(1e24),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(1e18)
            })
        }));
        vm.stopPrank();

        // Now read the payoff definition
        PayoffDefinition memory result = c.payoffDefinition();

        // Assert that the data field matches exactly
        assertTrue(result.data == data);
    }
}

contract MockOracle {
    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(1e18)});
    }
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(1e18)});
    }
    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(1e18)});
    }
}

contract MockController {
    function isContract(address) external pure returns (bool) { return true; }
    function collateral() external view returns (ICollateral) { return ICollateral(address(0)); }
    function incentivizer() external view returns (IIncentivizer) { return IIncentivizer(address(0)); }
    function paused() external view returns (bool) { return false; }
