    function owner(uint256) external view returns (address) { return address(0); }
    function treasury(uint256) external view returns (address) { return address(0); }
    function minFundingFee() external view returns (UFixed18) { return UFixed18.wrap(0); }
    function isProduct(IProduct) external view returns (bool) { return false; }
    function productBeacon() external view returns (IBeacon) { return IBeacon(address(0)); }
    function programsPerProduct() external view returns (uint256) { return 0; }
