// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        // We need a controller that is a contract to pass initialization checks;
        // deploy a minimal mock controller that implements the required interface partially.
        MockController mockCtrl = new MockController();
        vm.prank(address(mockCtrl));
        c = new C();
    }

    function testFuzz_property(bytes30 fuzzData) public {
        // The bug zeroes the data field; the reference keeps it.
        // We deploy a fresh C via a mock controller that initializes it with arbitrary fuzzData,
        // then read payoffDefinition() and compare its data field to the original fuzzData.

        // Deploy mock oracle and product info
        MockOracle oracle = new MockOracle();
        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "test",
            symbol: "TST",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType.NONE,
                payoffDirection: PayoffDefinitionLib.PayoffDirection.NEITHER,
                data: fuzzData
            }),
            oracle: IOracleProvider(address(oracle)),
            maintenance: UFixed18Lib.ZERO,
            fundingFee: UFixed18Lib.ZERO,
            makerFee: UFixed18Lib.ZERO,
            takerFee: UFixed18Lib.ZERO,
            positionFee: UFixed18Lib.ZERO,
            makerLimit: UFixed18Lib.MAX,
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });

        C product = new C();
        vm.prank(address(new MockController2()));
        product.initialize(info);

        PayoffDefinition memory returned = product.payoffDefinition();
        assertEq(returned.data, fuzzData, "data field must match original");
    }
}

// Minimal mocks to pass initialization without importing full contracts
