    function coordinatorFor(IProduct) external pure returns (uint256) { return 0; }
    function collateral() external view returns (ICollateral) { return ICollateral(address(0)); }
    function multiInvoker() external view returns (IMultiInvoker) { return IMultiInvoker(address(0)); }
    function incentivizer() external view returns (IIncentivizer) { return IIncentivizer(address(0)); }
    function paused() external pure returns (bool) { return false; }
