    function sync() external pure returns (OracleVersion memory) {
        return OracleVersion({ version: 0, timestamp: 0, price: Fixed18Lib.ZERO });
    }
    function currentVersion() external view returns (OracleVersion memory) {
        return OracleVersion({ version: 0, timestamp: 0, price: Fixed18Lib.ZERO });
